import subprocess
import time
import json
import platform
LOGFILE_PATH = "logfile.log"
def task_func(interval, duration):
    if interval <= 0 or duration <= 0:
        raise ValueError("Interval and duration must be positive")

    logs = []
    start_time = time.time()
    system = platform.system()

    while time.time() - start_time < duration:
        try:
            if system == "Windows":
                output = subprocess.check_output("wmic cpu get loadpercentage", shell=True).decode()
                cpu_usage = int(output.split('\n')[1].strip())
            else:
                output = subprocess.check_output("top -bn1 | grep 'Cpu(s)' | awk '{print $2 + $4}'", shell=True).decode()
                cpu_usage = float(output.strip())

            logs.append({"timestamp": time.time(), "cpu_usage": cpu_usage})
        except Exception:
            pass

        time.sleep(interval)

    try:
        with open(LOGFILE_PATH, 'w') as f:
            json.dump(logs, f)
        return LOGFILE_PATH
    except IOError:
        return None

